pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Dead-space penalty grows steeply for residuals too small to host typical items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 60.0 }
                   else if post_residual < 20 { 25.0 }
                   else if post_residual < 30 { 8.0 }
                   else if post_residual < 40 { 2.0 }
                   else { 0.0 };
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward residuals that exactly accommodate the next item (harmonic chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            // Slightly favor leaving room for the lookahead item.
            score -= 5.0 + 10.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // Leftover cannot host the next item: penalize proportionally.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Modulo-class logic: residuals that are multiples of common item sizes are reusable.
    let r = post_residual;
    if r >= 10 && (r % 10 == 0 || r % 20 == 0 || r % 25 == 0 || r % 50 == 0) {
        score -= 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full or item is huge.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / 10.0;
        let big_item = (item_size as f64 / bin_capacity as f64).powi(2) * 30.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 25.0 * mean_fill - 2.0 * pressure - big_item - 5.0 * progress;
    }

    // Mild preference for tighter bins overall relative to fleet mean residual.
    score += 0.3 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Dead-space avoidance: small unusable gaps are penalized hard.
    let dead_max: u32 = 12;
    if post_residual > 0 && post_residual <= dead_max {
        score += (dead_max as f64 + 1.0 - post_residual as f64) * 18.0;
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 2 {
        score -= 10.0;
    }

    // Lookahead: exact gap match for next item is best.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 52.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        let rem_after_next = post_residual - next_item_size;
        let tightness = 1.0 - (rem_after_next as f64) / 14.0;
        if tightness > 0.0 {
            score -= 34.0 * tightness;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead gap relative to lookahead item: penalize scaled by tightness.
        let gap = next_item_size as f64 - pr;
        let tightness = 1.0 - (pr / (next_item_size as f64 + 1.0));
        let progress = step_index as f64 / (total_items as f64 + 1.0);
        let weight = 0.55 + 0.95 * tightness - 0.25 * progress;
        score += weight * gap;
        let dead_threshold = cap * 0.18;
        if (post_residual as f64) < dead_threshold {
            score += 8.0 * (1.0 - post_residual as f64 / dead_threshold);
        }
    }

    // Reward using the last fitting bin before opening a new one (avoid waste).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild open-bin pressure.
    score += open_bins_count as f64 * 1.5;

    // Global residual alignment: prefer bins whose residual tracks mean residual.
    let dev = mean_residual - bin_residual as f64;
    if fitting_bins_count > 1 {
        score += 0.75 * dev;
    } else {
        score += 0.45 * dev;
    }

    // Prefer fuller bins: penalize large remaining residual fraction.
    let frac = bin_residual as f64 / cap;
    if frac > 0.45 && bin_residual != bin_capacity {
        score += 9.0 * (frac - 0.45);
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let mut nb = 55.0 - it * 0.4;
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            nb += progress * 20.0;
        }
        nb += fitting_bins_count as f64 * 4.0;
        if post_residual >= 20 && post_residual <= 60 {
            nb += 10.0;
        }
        if post_residual > 0 && post_residual <= dead_max {
            nb += (dead_max as f64 + 1.0 - post_residual as f64) * 18.0;
        }
        // Lookahead-aware: fresh bin leaves exactly the next item's size as gap.
        if next_item_size > 0 && post_residual == next_item_size {
            nb -= 20.0;
        }
        // Open new bin only for very large items that would leave tiny dead gaps.
        if pr <= 2.0 && next_item_size as f64 > 0.9 * cap {
            nb -= 20.0;
        } else {
            nb += 6.0 + 0.05 * open_bins_count as f64;
        }
        score = nb;
    }

    // Slight preference for tighter bins among equally-good fits.
    score += (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nxt = next_item_size as f64;

    // Lookahead-driven gap shaping (combined fine-grained + anticipation).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 58.0;
        } else if post_residual > next_item_size {
            let rem_after_next = post_residual - next_item_size;
            let tightness = 1.0 - (rem_after_next as f64) / 13.0;
            if tightness > 0.0 {
                score -= 40.0 * tightness;
            }
            if rem_after_next >= 1 && rem_after_next <= 4 {
                score -= 5.0;
            }
        } else {
            let dead_threshold = cap * 0.16;
            let dead = pr;
            if dead < dead_threshold {
                score += 20.0 * (1.0 - dead / dead_threshold);
            }
        }
    }

    // Dead-space avoidance for small unusable gaps.
    let dead_max: u32 = 9;
    if post_residual > 0 && post_residual <= dead_max {
        score += (dead_max as f64 + 1.0 - post_residual as f64) * 15.0;
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 2 {
        score -= 12.0;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 7.0;
    }

    // Reward using the last fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean-residual pull: prefer bins whose leftover beats the average.
    score -= 0.75 * (mean_residual - pr);

    // Mild open-bin pressure.
    score += open_bins_count as f64 * 1.0;

    // Borrowed: penalize gaps too small for the next item, weighted by tightness.
    if next_item_size > 0 && pr > 0.0 && pr < nxt {
        let gap = nxt - pr;
        let tightness = 1.0 - (pr / (nxt + 1.0));
        let progress = step_index as f64 / (total_items as f64 + 1.0);
        let weight = 0.55 + 0.95 * tightness - 0.25 * progress;
        score += weight * gap;
    }

    // Borrowed: reward slack that still hosts the next item when moderate.
    if next_item_size > 0 && pr >= nxt {
        let slack = pr - nxt;
        if slack < 0.35 * cap {
            score += 0.9 * slack * (1.0 - slack / cap);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 70.0 - it * 0.55 + progress * 24.0;
        score += fitting_bins_count as f64 * 7.0;
        if post_residual >= 16 && post_residual <= 55 {
            score += 13.0;
        }
        if post_residual > 0 && post_residual <= dead_max {
            score += (dead_max as f64 + 1.0 - post_residual as f64) * 15.0;
        }
        if progress > 0.65 {
            score += 20.0;
        }
        if next_item_size > post_residual {
            score += 9.0;
        }
        if item_size >= 60 {
            score -= 10.0;
        }
        // Borrowed: allow new bin when item nearly fills it and next item is huge.
        if pr <= 2.0 && nxt > 0.9 * cap {
            score -= 20.0;
        }
    }

    // Slight preference for tighter bins among equally-good fits.
    score += (bin_residual as f64 / cap) * 3.0;

    score
}

