pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / 50.0).max(0.0);
    } else if next_item_size > 0 {
        // Penalize bins that cannot host the next item, scaled by how much is wasted.
        score += 0.15 * post_residual as f64;
    }

    // Penalize dead space that no plausible future item can use
    // (items are >= 1; anything below a small threshold is dead).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-full bin is fine, but tiny unusable slivers
    }

    // Relative-to-mean coupling: prefer bins with residual below the mean
    // (consolidate small leftovers) when the fit is decent.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere (post_residual here is bin_capacity - item_size).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins with decent fits;
