        }
    }

    // New-bin candidate (bin_residual == bin_capacity): baseline cost of opening
    // a bin; only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 2.0;
        // Large items (>= 70) fit best in a fresh bin.
        if item_size >= 70 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64 * 1.5;

    // Perfect 2-step lookahead match: next item exactly fills the post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            // Chain completion: this bin gets closed by the next item — huge reward.
            score -= 45.0;
        } else if next_item_size < post_residual {
            // Next item also fits here; reward proportionally to how much it consumes.
            let consume_ratio = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * consume_ratio;
        } else {
            // Next item won't fit: penalize small dead space that nothing can use later.
            score += 8.0;
        }
    }

    // Penalize unusable slivers: post_residual smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Reward exact fit (item perfectly fills the bin now).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: only one bin can fit this item; using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving less than the average is good (denser packing than typical).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, be slightly more willing to spread items (open bins cheaply);
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // Mild penalty for leaving very large post_residual when it can't be matched by next item.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && post_residual < item_size {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: low post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize large dead space that is hard to reuse (post_residual small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny slivers are wasted capacity
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to leftover.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins (keep options open);
    // late in the stream, consolidate to avoid leftover bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: reward early, penalize late.
        score -= 25.0 * (1.0 - progress);
        score += 15.0 * progress;
        // Also prefer new bin when open bins are mostly full on average.
        if mean_residual < 20.0 {
            score -= 8.0;
        }
    } else {
        // Existing bin: slightly favored late in the stream.
        score -= 10.0 * progress;
    }

    // Global pressure: many open bins -> consolidate; few open bins -> flexibility.
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64 - 4.0).min(10.0) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good consolidation target.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.1 * (mean_residual - residual_f);
    } else {
        score += 0.05 * (residual_f - mean_residual);
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, but its weight grows with stream progress
    let mut score = pr * (0.7 + 0.6 * progress * progress);

    // Non-linear coupling: reward tight fits via smooth decay of post_residual
    score -= 30.0 * (-norm_pr * norm_pr * 12.0).exp() * (0.5 + 0.5 * progress);

    // Penalize moderately-large dead space quadratically (unusable gaps)
    score += 4.0 * norm_pr * norm_pr * cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Crowd penalty: with many open bins, prefer consolidating into existing ones
    score += (open_bins_count as f64).sqrt() * 0.8 * (1.0 - progress);

    // Mean residual coupling: prefer bins whose residual is below the mean (compact them)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0) * (0.4 + 0.6 * progress);

    // Lookahead: if next item fits exactly into the resulting residual, reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-gap * gap / 50.0).exp();
        // Penalize residuals that fit neither the next item nor much else
        if pr < next_item_size as f64 && pr < 10.0 {
            score += 5.0;
        }
    }

    // New-bin candidate: smooth penalty modulated by progress and fit quality
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 18.0 * (-norm_pr * 0.0).exp();
        // allow new bin late in stream when fits are poor
        score -= 8.0 * progress * (1.0 - (pr / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes
    let pr = post_residual;
    let pr_mod = (pr % 10) as f64;
    let pr_div = (pr / 10) as f64;

    // Penalize residuals in "awkward" harmonic classes (mod 10 != 0) more
    if pr_mod > 0.0 {
        score += pr_mod * 0.7;
    } else {
        // perfectly divisible residual: reward
        score -= 4.0;
    }

    // Dead-space threshold via integer division: post_residual < 10 is pure waste
    if pr < 10 && pr > 0 {
        score += 25.0;
    }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        let fits_next = next_item_size <= pr;
        if fits_next {
            // reward if next item leaves a class-0 residual too
            let npr = pr - next_item_size;
            if npr % 10 == 0 {
                score -= 12.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: penalize by leftover size
            score += (next_item_size.min(pr)) as f64 * 0.3;
        }
        // exact pairing: next item exactly fills the bin
        if next_item_size == pr {
            score -= 30.0;
        }
    }

    // Capacity fraction thresholds: post_residual relative to capacity
    let frac = pr as f64 / bin_capacity as f64;
    if frac < 0.25 {
        score += 8.0; // small residual: low utility
    } else if frac > 0.6 {
        score -= 6.0; // large residual: roomy, good
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // spread load when many bins fit
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate handling: neutral baseline so it wins only when fits are bad
    if bin_residual == bin_capacity {
        // new bin baseline: its post_residual is large but it should not
        // automatically win; add a fixed opening cost
        score += 15.0;
        // opening a new bin is more attractive early / when few bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0 + open_bins_count as f64 * 0.5;
        // if next item is huge, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter packing)
    score -= (mean_residual - pr as f64).max(0.0) * 0.2;

    // Step-based drift: later in stream, be greedier about exact fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    if item_size == pr {
        score -= 40.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for typical future
    // items (below the minimum plausible size) are worthless — penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // A gap that cannot fit the lookahead item is likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 18.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than fragmenting space further.
    score += open_bins_count as f64 * 0.8;

    // Slight preference for bins already below average residual
    // (consolidate fullness) — penalize bins with excess residual.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.05;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // fit into any open bin would create severe dead space.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && (post_residual < 10 || (next_item_size > 0 && post_residual < next_item_size as f64));
        if bad_fit {
            score -= 10.0; // opening fresh bin is competitive
        } else {
            score += 45.0; // keep using open bins when fit is decent
        }
    }

    // Early in the stream, tolerate opening bins slightly more (future flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match: next item leaves a small remainder after the lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem_after_next = post_residual - next_item_size;
        // Reward small leftovers after the next item (tight 2-item packing).
        score -= 30.0 * (1.0 - (rem_after_next as f64) / 20.0).max(0.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use this bin's remainder.
        // Penalize small dead space heavily (unusable slivers).
        let dead = post_residual as f64;
        score += 12.0 * (1.0 - dead / (bin_capacity as f64 * 0.25)).max(0.0);
    }

    // Last-chance bonus: only one bin fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare residual against mean residual: prefer bins that are already
    // relatively full (residual below mean) to consolidate packing.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild pressure to close bins early in the stream; new-bin fallback
    // (residual == capacity) gets a slight handicap so open bins win ties.
    if bin_residual == bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual gets a bonus.
    let tight_fit_bonus = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 8.0 * tight_fit_bonus * tight_fit_bonus;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.05 * dead * (1.0 + dead / 50.0);
            }
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Crowding pressure: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        let crowd = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)) * (0.5 + progress);
        score -= 0.3 * crowd.min(5.0);
    }

    // New-bin candidate: penalize opening a new bin, more strongly early on
    // (keeping bins consolidated) and when the item is small.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 12.0 + 20.0 * (1.0 - progress) + 0.15 * item_size as f64;
        score += new_bin_penalty;
        // But if item is huge and nothing fits well, new bin is fine.
        if item_size >= 70 {
            score -= 18.0;
        }
    }

    // Discourage leaving residuals that almost nothing can use (very small gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Mild preference for bins with below-average residual (denser bins first).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / c;
    let fill = 1.0 - pr / c;

    // Smooth polynomial coupling: post_residual scaled by progress-dependent weights
    let prog_sq = progress * progress;
    let prog_w = 0.5 + 1.5 * prog_sq; // later in stream: penalize large residuals more
    let mut score = pr * prog_w;

    // Non-linear reward for high fill fraction (cubic smoothness)
    score -= 12.0 * fill * fill * fill;

    // Interaction: small post-residual is valuable when stream is advanced
    let tight = (c - pr) / c;
    score -= 8.0 * tight * tight * progress;

    // Penalize dead space that next item cannot use (smooth coupling)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / c;
        score += 10.0 * gap * gap * (1.0 - progress);
        // reward exact-ish fit for next item
        let use_next = (next_item_size as f64 / pr.max(1.0)).min(1.0);
        score -= 6.0 * use_next * use_next;
    }

    // Last-chance bonus (smoothly scaled by scarcity)
    if fitting_bins_count <= 1 {
        score -= 15.0 * fit_ratio;
    }

    // Slight preference for bins below mean residual (balance spreading)
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: mild penalty so it only wins when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction slot it lands in.
    // Classes: (0..=10] near-perfect, (10..=25] small, (25..=50] medium, (50..=100] large.
    let class: f64 = if post_residual == 0 {
        0.0
    } else if post_residual <= 10 {
        1.0
    } else if post_residual <= 25 {
        2.0
    } else if post_residual <= 50 {
        3.0
    } else {
        4.0
    };
    score += class * 7.0;

    // Integer-division harmonic: post_residual / 10 bucket, mildly rewarding tight fits.
    let decile = (post_residual / 10) as f64;
    score -= 3.0 * (9.0 - decile.min(9.0));

    // Dead-space penalty: residual too small for the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance: only this bin fits the item -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item can exactly fill the post residual,
    // reward heavily (perfect harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize wasting space it could have used elsewhere.
            score += 4.0;
        }
    }

    // Modulo arithmetic on post_residual vs capacity: residuals that are nice
    // divisors/fractions of capacity are more reusable.
    if post_residual > 0 && (bin_capacity % post_residual == 0 || post_residual % 10 == 0) {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item would leave an awkward residual in every existing bin, or bins are few.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: score equals residual (capacity) minus a discount
        // that grows when existing bins are congested.
        score = post_residual as f64 - 15.0
            - 10.0 * (mean_residual / cap)
            - (open_bins_count as f64).sqrt() * 2.0;
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If only one bin fits and it's not this one, discourage new bin implicitly
        // by making fresh bin less attractive when a fitting bin exists.
        if fitting_bins_count >= 1 {
            score += 12.0;
        }
    }

    // Slight preference to fill bins that are already relatively full.
    score -= 10.0 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible item (min size 1, but small gaps < ~15 are near-unusable)
    // become expensive dead space.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 10.0;

    // Penalize leaving a gap that cannot fit the lookahead item but could
    // have if we chose differently — mild lookahead coupling.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size && (bin_residual as u32) >= next_item_size {
            score += 4.0;
        }
        if (post_residual as u32) >= next_item_size {
            score -= 3.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: make it unattractive unless the item fits very
    // poorly everywhere (handled via tightness/last-chance terms).
    if bin_residual == bin_capacity {
        score += 6.0 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // 2-step lookahead: reward when the next item exactly fills the post residual,
    // penalize when the next item cannot fit into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: this bin becomes exactly full
        } else if next_item_size <= post_residual {
            // next fits but leaves a gap; smaller leftover gap is better
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: dead space risk
            score += 10.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins with less residual than average
    // (consolidate filling), avoid dumping into already-large-residual bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when open-bin fits are bad.
        score += 25.0;
        // Early in stream, opening bins is cheap and useful for future flexibility.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If many bins are open already, discourage spreading.
        score += open_bins_count as f64 * 1.5;
        // If the next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Mild penalty for very high fragmentation (tiny unusable leftover).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
        // Perfect chaining: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large relative to capacity or open bins are already numerous.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        let attraction = 40.0 + 0.5 * item_size as f64 - 3.0 * pressure - 10.0 * progress;
        score = score.min(attraction.max(2.0) + post_residual as f64 * 0.1);
        // Large items fit fine anywhere; prefer a fresh bin for them.
        if item_size >= 70 {
            score -= 25.0;
        }
    }

    // Global balance: prefer bins whose residual is near the mean (avoid
    // fragmenting one bin while leaving others untouched).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for filling more-loaded bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pn = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = pr as f64;

    // Non-linear coupling: small post-residuals get quadratically rewarded,
    // with strength growing as the stream progresses.
    let tightness = (1.0 - pn).powi(2);
    score -= 30.0 * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space: cubic penalty on unusable residual (< smallest plausible item).
    let dead = ((20.0 - pr) / 20.0).max(0.0);
    score += 25.0 * dead.powi(3);

    // Reward exact/near fit of next item into post-residual (smooth kernel).
    if nxt > 0.0 {
        let gap = (pn * cap - nxt) / cap;
        if gap >= 0.0 {
            score -= 20.0 * (-8.0 * gap * gap) .exp() * (0.5 + 0.5 * progress);
        } else {
            score += 5.0 * (gap.abs() / cap);
        }
    }

    // Last-chance bonus: strongly favor using a scarce fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pn);
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize opening fresh bins early, allow late in stream
    // only when post-residual would be large (poor fits elsewhere).
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress).powi(2);
        score -= 10.0 * progress * pn;
    }

    // Cubic stream-progress modulation of residual weight: late stream values
    // tight packing more strongly.
    score += 10.0 * pn * pn * pn * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quantize item into capacity eighths.
    let item_class = (item_size * 8) / bin_capacity;           // 0..=8
    let post_class = (post_residual * 8) / bin_capacity;       // dead-space class

    // Reward tight fits strongly: exact/near-exact residual gets big subtraction.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= bin_capacity / 16 {
        score -= 40.0;
    } else {
        // Penalize dead space quadratically within its harmonic class.
        score += (post_class as f64) * (post_class as f64) * 2.5;
    }

    // Harmonic pairing: reward bins whose post_residual can host next_item_size
    // exactly or in a complementary class (classic modular complement logic).
    if next_item_size > 0 && next_item_size <= post_residual {
        let complement = (bin_capacity - item_size).min(post_residual);
        if next_item_size == complement {
            score -= 30.0;
        } else {
            score -= 12.0;
        }
        // Extra reward if next item then leaves a clean class boundary.
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 15.0;
        } else if (next_post * 8) % bin_capacity == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: mild penalty.
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: opening a bin is expensive; penalize unless this bin
    // would otherwise waste the item badly or the bin is genuinely full.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if no open bin fits at all, the new-bin call must win.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer closing out residual space over new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 {
            score += 10.0;
        }
    }

    // Prefer bins with residual below the mean (consolidate emptier bins).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // Prefer already-open bins (avoid bin proliferation).
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize gaps that can't hold a meaningful follow-up item.
    let dead_threshold = 12.0; // gaps below ~12 are rarely reusable
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward post_residuals that can still hold a typical next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 {
        // Post-residual cannot fit the lookahead item: penalize proportionally.
        score += (next_item_size - post_residual.min(next_item_size)) as f64 * 0.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual is high.
    let open_pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score += open_pressure * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless open bins are nearly full.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.0; // base penalty for opening new bins
        if mean_residual < 8.0 {
            // All open bins nearly full: opening a new bin is fine.
            score -= 12.0;
        }
    }

    // Late-stream tightening: as stream progresses, prefer tighter fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: superlinear in waste
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // 2-step lookahead: reward exact chain fits (item + next item fill residual)
    if next_item_size > 0 {
        let chain = item_size as f64 + next_item_size as f64;
        if chain as u32 == bin_residual {
            score -= 60.0; // perfect 2-item fill
        } else if next_item_size as u32 <= post_residual {
            score -= 25.0; // next item still fits after placement
        } else {
            // next item won't fit: post_residual likely becomes dead space
            score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Reward tight fits relative to mean residual
    if (bin_residual as f64 - item_size as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        if pressure > 0.0 {
            score -= 20.0; // open a new bin when no open bin fits
        } else {
            score += 30.0; // discourage opening new bins when fits exist
        }
    }

    // Mild stream-progression bias: consolidate more as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Penalize waste when the item nearly empties the bin (good) vs leaving awkward gaps.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += 12.0; // dead space below min item size
    } else if gap >= 10.0 && next_item_size > 0 && (next_item_size as f64) <= gap {
        // Lookahead: bonus if the next item fits this bin's post residual
        score -= 8.0 * (1.0 - (next_item_size as f64 / gap));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to preserve flexibility elsewhere.
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Time horizon: early in the stream, be conservative (penalize fragmentation);
    // late in the stream, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Global state coupling: prefer bins with residual below mean (consolidate fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Penalize opening a new bin when good alternatives exist; encourage it only
    // when open bins are crowded and item is large.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 20.0;
        let big_item = item_size > 60;
        if !crowded || !big_item {
            score += 18.0;
        } else {
            score += 4.0;
        }
    }

    // Mild penalty for many open bins to discourage bin sprawl.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Penalize small-but-nonzero dead space quadratically (waste shaping)
    let dead = norm_pr * (1.0 - norm_pr);
    score += 18.0 * dead * (0.5 + progress);

    // Reward tight fits: subtract when post_residual is very small
    score -= 10.0 * (-pr / 12.0).exp() * (1.0 + 0.5 * progress);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * progress;
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs() * cap;

    // New-bin candidate handling: make empty bin mildly unattractive early,
    // more attractive late or when many bins already open
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 5.0 * progress;
        score += 0.3 * open_bins_count as f64;
    }

    // Fragmentation penalty: heavily reward filling bins completely
    score -= 4.0 * norm_item * norm_item * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes.
    // Small residuals that can't fit any plausible item (min size 1..) are dead space.
    let pr = post_residual;
    let class = pr / 10; // integer division into decade classes (0..10)
    let dead_penalty: f64 = match class {
        0 => 60.0, // post_residual 0..9: nearly dead space
        1 => 40.0, // 10..19: fits only tiny items
        2 => 22.0,
        3 => 12.0,
        4 => 5.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Modulo coupling: residuals of the form 100k boundaries are valuable;
    // penalize residuals that are awkward modulo 10 (odd slivers).
    if pr > 0 {
        let m = pr % 10;
        score += (5 - m.abs_diff(0) as i32).max(0) as f64 * 0.5;
        if pr % 2 == 1 { score += 1.0; }
    }

    // Perfect fit reward: post_residual zero is ideal.
    if pr == 0 { score -= 50.0; }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 && pr >= next_item_size {
        let slack = pr - next_item_size;
        score -= 8.0 - (slack as f64) * 0.15; // tight lookahead fit is good
        if slack == 0 { score -= 10.0; } // chain of perfect fits
    } else if next_item_size > 0 && next_item_size <= bin_residual && pr < next_item_size {
        // This placement kills ability to host next item in this bin; mild penalty.
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost so we prefer
    // reusing open bins with good fits, but keep it attractive for bad fits.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * (open_bins_count as f64);
        // If item is large relative to capacity, opening fresh is fine.
        if (item_size as f64) > 0.6 * cap { score -= 12.0; }
    }

    // Progress coupling: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (post_residual as f64 / cap);

    // Prefer bins tighter than average (best-fit refinement).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    if next_item_size > 0 && post_residual > next_item_size {
        let rem_after_next = post_residual - next_item_size;
        // Tight 2-item packing: reward small leftovers, scaled by how much
        // of the remainder the next item consumes (lookahead efficiency).
        let consumed_frac = next_item_size as f64 / post_f;
        score -= 32.0 * (1.0 - (rem_after_next as f64) / 25.0).max(0.0) * (0.5 + 0.5 * consumed_frac);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use this bin's remainder.
        // Penalize slivers harder as fraction of capacity; but a very small
        // dead space (< 3) is nearly free, soften the penalty there.
        let dead = post_f;
        let frac = dead / cap_f;
        if dead < 3.0 {
            score += 4.0;
        } else {
            score += 14.0 * (1.0 - frac / 0.25).max(0.0);
        }
    }

    // Chain-fit lookahead: if the remainder after next item would be a
    // perfect fit for a very small follow-up, keep the door open.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem <= 5 {
            score -= 6.0; // near-perfect triple chain
        }
    }

    // Last-chance bonus: only one bin fits; strongly prefer using it,
    // stronger when the stream is late (fewer chances to fix waste).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let urgency = 12.0 + 8.0 * (step_index as f64 / total_items.max(1) as f64);
        score -= urgency;
    }

    // Compare residual against mean residual: prefer consolidating into
    // fuller bins, but cap the pull so it never dominates the lookahead.
    let mean_pull = 0.5 * (mean_residual - post_f);
    score += mean_pull.max(-15.0).min(15.0);

    // Occupancy bonus: reward bins that are already substantially filled,
    // scaled by progress through the stream (front-load consolidation).
    let occupancy = 1.0 - bin_residual as f64 / cap_f;
    score -= 6.0 * occupancy * (0.5 + 0.5 * step_index as f64 / total_items.max(1) as f64);

    // New-bin fallback: handicap grows when many bins are open (avoid
    // bin sprawl), shrinks late in the stream when consolidation is done.
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * (open_bins_count as f64 / 50.0).min(1.0)
            - 2.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Near-match: next item leaves a small remainder after the lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem_after_next = post_residual - next_item_size;
        // Reward small leftovers after the next item (tight 2-item packing),
        // with a sharper decay so only genuinely tight fits benefit.
        let tightness = 1.0 - (rem_after_next as f64) / 14.0;
        if tightness > 0.0 {
            score -= 34.0 * tightness;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use this bin's remainder.
        // Penalize slivers that are too small for typical items.
        let dead = post_residual as f64;
        if dead < cap * 0.18 {
            score += 16.0 * (1.0 - dead / (cap * 0.18));
        }
    }

    // Last-chance bonus: only one bin fits; strongly prefer using it.
    // Escalate when the stream is large (consolidation pressure).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Compare residual against mean residual: prefer bins that are already
    // relatively full (residual below mean) to consolidate packing.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: a fresh bin is only attractive when no open
    // bin offers a decent fit. If several bins fit, handicap the new bin so
    // open bins win; if the item barely fits anywhere, allow opening a bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count >= 2 {
            score += 8.0;
        } else if fitting_bins_count == 1 {
            // Only open a new bin if the existing fit is very loose.
            let slack = bin_residual - item_size;
            if slack > bin_capacity / 4 {
                score += 5.0;
            } else {
                score += 1.0;
            }
        } else {
            // No open bin fits: new bin is the only option; slight nudge.
            score -= 1.0;
