    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Exact / near-exact fill
    if pr == 0 {
        score -= 50.0 * (0.6 + progress);
    } else if pr <= 2 {
        score -= 12.0;
    } else if pr <= 5 && next_item_size > 0 && next_item_size <= pr {
        score -= 7.0;
    } else if pr < 8 {
        score += 20.0 * (1.0 - pr as f64 / 8.0);
    }

    // Lookahead coupling with next item (tightness-scaled core)
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 52.0;
        } else if pr > next_item_size {
            let rem = pr - next_item_size;
            let tightness = 1.0 - rem as f64 / 14.0;
            if tightness > 0.0 {
                score -= 34.0 * tightness;
            } else {
                score -= 2.0;
            }
            if rem % 10 == 0 {
                score -= 6.0;
            }
            // chain-fill: after next item, residual matches current item again
            if rem == item_size {
                score -= 18.0;
            }
        } else {
            // next item cannot fit here; penalize dead residual
            let dead_threshold = cap * 0.18;
            if pr < 10 {
                score += 20.0;
            } else if (pr as f64) < dead_threshold {
                score += 16.0 * (1.0 - pr as f64 / dead_threshold);
            }
        }
    }

    // Harmonic class reward
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Prefer bins tighter than the mean residual
    score -= 0.6 * (mean_residual - pr as f64).max(0.0);

    // Small penalty for unusable small residuals
    if pr > 0 && (next_item_size == 0 || next_item_size > pr) && pr < 20 {
        score += (20 - pr) as f64 * 0.45;
    }

    // Two-item lookahead: chain-fill reward
    if next_item_size > 0 && pr > next_item_size {
        let rem2 = pr - next_item_size;
        if rem2 == item_size {
            score -= 20.0;
        }
        if rem2 > 0 && next_item_size > 0 && rem2 % next_item_size == 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 0.8;
    }

    // New-bin candidate: baseline opening cost with adaptive discount
    if bin_residual == bin_capacity {
        score += 15.0;
        score -= (1.0 - progress) * 7.0 + open_bins_count as f64 * 0.4;
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 7.0;
        }
        // opening a fresh bin is attractive when all existing fits are poor:
        // no existing bin can hold the next item either
        if fitting_bins_count > 0 && next_item_size > 0 {
            let usable = fitting_bins_count as f64;
            let poor = open_bins_count as f64 - usable;
            if next_item_size > pr && poor / (open_bins_count.max(1) as f64) > 0.5 {
                score -= 6.0;
            }
        }
        score -= (pr as f64 / cap) * 6.0;
    }

    // Late-stream greediness
    if item_size == bin_residual {
        score -= 36.0 * (0.5 + progress);
    }

    // Dead-space ratio penalty: residual nothing upcoming can use
    if next_item_size > pr && pr > 0 {
        let waste_ratio = pr as f64 / cap;
        score += 14.0 * waste_ratio;
    }

    // Fractional-fit reward: item fills a large share of the bin exactly
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if item_size <= bin_residual && fill > 0.8 {
        score -= 10.0 * (fill - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "dead" if it's smaller than the smallest plausible item (1..100 range, assume >= 10-ish granularity).
    // Use a smooth super-linear penalty on post_residual when it's small.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // dead-space zone: gaps that are too small to be useful
        let dead_threshold = 12.0_f64;
        if pr < dead_threshold {
            score += (dead_threshold - pr) * (dead_threshold - pr) * 4.0;
        }
        // general waste pressure: quadratic growth of wasted capacity
        score += pr * pr / (bin_capacity as f64) * 0.5;
    } else {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits relative to item size (waste ratio)
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Open-bins pressure: penalize leaving many bins open, encourages consolidation
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins unattractive unless the current
    // bin fit would be really bad (large dead space) or the bin is a poor host
    // for the lookahead item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin
        score += 45.0 + open_pressure * 1.5;
        // if the item would leave a large gap in every existing bin, new bin is fine
        if pr >= item_size as f64 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item would NOT fit post-residual but would fit an empty bin, and this
    // placement leaves a big gap, penalize slightly.
    if next_item_size > 0 && post_residual < next_item_size && pr > 0.0 {
        score += (pr / 10.0) * 2.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins),
    // leaving large-residual bins for bigger future items.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.15;
    }

    // Stream progression: early on, be a bit more liberal about opening bins;
    // late in stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 {
        score += 8.0 * (1.0 - progress); // reduce new-bin attractiveness late
        if is_new_bin { score += 20.0 * progress; }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let res = post_residual as f64 ;

    // Lookahead: reward leaving exactly the next item's size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 52.0 ;
    } else if next_item_size > 0 && post_residual > next_item_size {
        let rem_after_next = post_residual - next_item_size ;
        let tightness = 1.0 - (rem_after_next as f64) / 14.0 ;
        if tightness > 0.0 {
            score -= 34.0 * tightness ;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space penalty scaled by relative waste, not absolute threshold
        let dead_ratio = res / cap ;
        if dead_ratio < 0.18 {
            score += 16.0 * (1.0 - dead_ratio / 0.18) ;
        }
    }

    // Near-perfect fills
    if post_residual == 0 {
        score -= 25.0 ;
    } else if post_residual <= 2 {
        score -= 10.0 ;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 ;
    }

    // New-bin candidate: penalize opening a bin unless the item is large
    // relative to capacity or open bins are crowded (poor fits likely).
    if bin_residual == bin_capacity {
        let crowding = 1.0 - (fitting_bins_count as f64) / ((open_bins_count.max(1)) as f64) ;
        let item_rel = (item_size as f64) / cap ;
        // Prefer reusing when many bins fit; allow new bin for big items or crowded state
        score += 40.0 - 30.0 * crowding - 25.0 * item_rel ;
    }

    // Mild preference toward bins tighter than the fleet mean
    score -= 0.6 * (mean_residual - res) ;

    // Fractional dead-space term: discourage mid-range residuals that are
    // unlikely to be filled later (waste-prone zone).
    if res > 6.0 && res < cap * 0.35 {
        score += 0.15 * res ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // 2-step lookahead: perfect match => post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0; // perfect 2-step chain: this bin becomes exactly usable next step
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // next item still fits after this placement: mild reward, tighter is better
        score -= 8.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
    } else if next_item_size > 0 {
        // next item won't fit: penalize dead space proportionally to how close we came
        let miss = (next_item_size - post_residual) as f64;
        score += 0.35 * miss;
    }

    // Reward filling the bin tightly relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.25 * (pr - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large (poor fit anywhere) or few bins fit it and residual waste would be big.
    if is_new_bin {
        let waste_elsewhere = post_residual as f64; // residual of an empty bin = capacity
        // Penalize new bin mildly; the empty-bin call arrives with post_residual == capacity,
        // which already looks bad vs tight fits, but add explicit guard so we don't open
        // new bins when a decent fit exists.
        if fitting_bins_count > 0 && item_size <= bin_residual - item_size.max(0) {
            score += 40.0;
        }
        // Encourage new bin when item is huge relative to typical residual
        // (mean_residual small means open bins are nearly full).
        if mean_residual < item_size as f64 * 1.2 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        let _ = waste_elsewhere;
    }

    // Small penalty for leaving awkwardly small-but-unusable residuals (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.15 * post_residual as f64;
    }

    // Slight preference for keeping the number of open bins low.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
