}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small but nonzero.
    if post_residual > 0 {
        score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        score -= 20.0; // perfect fill
    }

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && next_item_size <= item_size {
        // next item larger than current: avoid wasting big residual
        score += 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of opening a new bin
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: new bin is correct
        } else if fitting_bins_count == 1 {
            score += 10.0; // last chance exists, avoid new bin
        }
        // Late in the stream, avoid opening bins that will stay mostly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer using bins with below-average residual (consolidate fullness).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild preference for fewer open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
