            } else {
                score -= 4.0;
            }
            if rem % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot fit here; penalize dead space proportionally
            let dead_threshold = cap * 0.18;
            if pr < 10 {
                score += 22.0;
            } else if (pr as f64) < dead_threshold {
                score += 16.0 * (1.0 - pr as f64 / dead_threshold);
            }
        }
    }

    // Prefer bins tighter than the mean residual
    score -= 0.6 * (mean_residual - pr as f64).max(0.0);

    // Last-chance bin: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 1.2;
