    // New-bin candidate: opening cost modulated by progress, load, and lookahead
    if bin_residual == bin_capacity {
        score += 14.0;
        score -= (1.0 - progress) * 8.0 + open_bins_count as f64 * 0.4;
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        score -= (pr as f64 / cap) * 6.0;
        // penalize opening a new bin when an existing bin would be nearly filled
        if fitting_bins_count > 0 && pr <= 10 {
            score += 24.0;
        }
        // penalize opening a new bin when next item exactly fills a candidate bin
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size <= bin_residual {
            let rem = bin_residual - next_item_size;
            if rem <= 10 {
                score += 30.0;
            }
        }
    }

    // Late-stream greediness: exact fits matter more near the end
    if item_size == bin_residual {
