    score += 0.4 * open_bins_count as f64;

    // New-bin candidate handling: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Exact / near-exact fill
    if pr == 0 {
        score -= 45.0 * (0.6 + progress);
    } else if pr <= 2 {
        score -= 12.0;
    } else if pr <= 5 && next_item_size > 0 && next_item_size <= pr {
        score -= 7.0;
    }

    // Lookahead coupling with next item (tightness-scaled core)
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 52.0;
        } else if pr > next_item_size {
            let rem = pr - next_item_size;
            let tightness = 1.0 - rem as f64 / 14.0;
            if tightness > 0.0 {
                score -= 34.0 * tightness;
            } else {
                score -= 2.0;
            }
            // chain-fill: after next item, residual matches current item again
            if rem == item_size {
                score -= 18.0;
            }
        } else {
            // next item cannot fit here; penalize dead residual
            let dead_threshold = cap * 0.18;
            if pr < 10 {
                score += 20.0;
            } else if (pr as f64) < dead_threshold {
                score += 16.0 * (1.0 - pr as f64 / dead_threshold);
            }
        }
    }

    // Prefer bins tighter than the mean residual (clipped to avoid over-rewarding)
    let tight = (mean_residual - pr as f64).max(0.0).min(cap * 0.5);
    score -= 0.6 * tight;

    // Small penalty for unusable small residuals
    if pr > 0 && (next_item_size == 0 || next_item_size > pr) && pr < 20 {
        score += (20 - pr) as f64 * 0.45;
    }

    // Last-chance bin: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline opening cost with adaptive discount
    if bin_residual == bin_capacity {
        score += 15.0;
        score -= (1.0 - progress) * 7.0 + open_bins_count as f64 * 0.4;
        if item_size >= bin_capacity * 3 / 4 {
            score -= 7.0;
        }
        score -= (pr as f64 / cap) * 6.0;
    }

    // Late-stream greediness
    if item_size == bin_residual {
        score -= 36.0 * (0.5 + progress);
    }

    // Fractional-fit reward: item fills a large share of the bin exactly
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if item_size <= bin_residual && fill > 0.8 {
        score -= 10.0 * (fill - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division tiers
    let r = post_residual % 10;
    let q = post_residual / 10;

    // Reward small post_residual strongly (tight fit)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.9;

    // Dead-space penalty grows super-linearly for mid-range residuals (hardest to fill)
    let mid = ((post_residual as f64) - 25.0).abs();
    score += 0.015 * mid * mid;

    // Modulo-10 classes: residuals that are multiples of 10 pair well with common item sizes
    if r == 0 { score -= 6.0; }
    if r == 5 { score += 3.0; }
    if r >= 1 && r <= 4 { score += 2.0 * r as f64; } // tiny unusable slivers

    // Integer-division tier bonus: q in 0..=2 means near-perfect packing
    if q <= 2 && post_residual > 0 { score -= 8.0; }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward if next item exactly fills, or leaves a multiple-of-10 class again
            let next_post = post_residual - next_item_size;
            if next_post == 0 { score -= 20.0; }
            if next_post % 10 == 0 { score -= 5.0; }
            score -= 2.0;
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally
            score += 4.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 25.0 } else if fitting_bins_count == 1 { 5.0 } else { 0.0 };
        score = 60.0 - urgency + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big next item benefits from fresh bin
        }
    }

    // Global residual balancing: prefer bins near mean residual for future flexibility
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    // Late-stream tightening: as stream ends, minimize leftover aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any positive residual below the minimum
    // item size (1..10 range) is pure waste — penalize it hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward near-perfect fits (post_residual very small but nonzero).
    if post_residual <= 3 {
        score -= 15.0;
    }

    // Reward exact fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that the lookahead item can exactly fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leaving a gap the next item just barely misses.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 5 {
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 4.0 + progress * 20.0;
        // But if this bin is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Last-chance bin: strongly favor using the final fitting bin
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild preference for bins below mean residual (spreading load evenly).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space avoidance: super-linear penalty for small unusable gaps.
    if pr > 0.0 {
        let dead_threshold = 12.0_f64;
        if pr < dead_threshold {
            score += (dead_threshold - pr) * (dead_threshold - pr) * 4.0;
        }
        score += pr * pr / cap * 0.5;
    } else {
        score -= 60.0;
    }

    // Reward tight fills relative to item size (scaled by item magnitude).
    if item_size > 0 && bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
        // Absolute tightness: near-exact fills of large residual space.
        if bin_residual - item_size <= 3 {
            score -= 12.0;
        }
    }

    // Open-bins pressure: encourage consolidation.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: only fitting bin -> prefer it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize more when open bins are few.
    if is_new_bin {
        score += 45.0 + open_bins_count as f64 * 1.5;
        if pr >= item_size as f64 {
            score -= 10.0;
        }
        // Late-stream: strongly discourage opening new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
    }

    // Lookahead coupling: exact-fit chain and tightness-aware anticipation.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 52.0;
        } else if post_residual > next_item_size {
            let rem_after_next = post_residual - next_item_size;
            let tightness = 1.0 - (rem_after_next as f64) / 14.0;
            if tightness > 0.0 {
                score -= 34.0 * tightness;
            }
        } else {
            let dead_threshold = cap * 0.18;
            if pr < dead_threshold {
                score += 16.0 * (1.0 - pr / dead_threshold);
            }
        }
    }

    // Mean-residual coupling: prefer tighter bins (borrowed, tuned).
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.45;
    }

    // Stream progression: consolidate harder late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 {
        score += 8.0 * (1.0 - progress);
    }

    // Small residual bonuses.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 10.0;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 52.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        let rem_after_next = post_residual - next_item_size;
        let tightness = 1.0 - (rem_after_next as f64) / 14.0;
        if tightness > 0.0 {
            score -= 34.0 * tightness;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        let dead_threshold = cap * 0.18;
        if dead < dead_threshold {
            score += 16.0 * (1.0 - dead / dead_threshold);
        }
    }

    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 10.0;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Prefer bins that remain useful after placement: penalize large leftover space
    // when it is "wasted" (much larger than the mean need), reward moderately tight fits.
    let pr = post_residual as f64;
    if pr > mean_residual * 1.6 {
        score += 4.0 * ((pr / cap) - 0.35).max(0.0) * 10.0;
    }

    // Scarcity pressure: when few bins can host this item, prefer the tightest of them.
    if fitting_bins_count <= 2 && bin_residual >= item_size {
        score -= 8.0 * (1.0 - item_size as f64 / bin_residual as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well or the item
    // is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (item_size as f64 / cap) > 0.6;
        if scarcity == 0.0 && !big_item {
            score += 14.0 + 0.05 * (open_bins_count as f64);
        } else if big_item && fitting_bins_count > 0 {
            score += 6.0;
        }
    }

    score -= 0.6 * (mean_residual - post_residual as f64);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: penalize opening a new bin unless it's
    // the only option or the fit in existing bins would be very poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // Forced: must open a new bin.
            score = -1000.0;
        } else {
            // Opening a new bin wastes the item_size worth of space in the
            // existing bin; penalize more when other bins fit well.
            let mut alt = 0.0;
            score = 150.0 + alt + (fitting_bins_count as f64) * 10.0;
            // If next item could pair with the fresh residual, mildly favor it.
            if (next_item_size as f64) <= post_residual as f64 && next_item_size > 0 {
                score -= 30.0;
            }
        }
        return score;
    }

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: post_residual exactly accommodates next item.
        if post_residual == next_item_size {
            score -= 120.0;
        } else if (post_residual as f64) >= next_item_size as f64 {
            // Next item still fits after this placement: reward closeness.
            score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit: penalize dead space proportional to gap.
            score += 0.5 * diff;
        }
    } else {
        // Last item: just minimize post_residual (tightest fit).
        score *= 2.0;
    }

    // Relative-to-mean coupling: bins with residual above mean have more
    // room to absorb future items; slightly favor keeping them tight.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Tight fit bonus: near-perfect fill of the bin.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Late in the stream, consolidation matters more; penalize leaving
    // large residuals in already-open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
