    if item_size == bin_residual {
        score -= 15.0;
    }

    // Fragmentation guard: tiny leftover after placing item that next item cannot use
    if pr > 0 && pr < 4 && next_item_size > pr {
        score += 10.0;
    }

    // NEW: combined residual-fit + lookahead coupling.
    // Reward bins whose post-fit residual is a near-exact multiple/half of the
