    if next_item_size > 0 && pr >= next_item_size {
        let rem2 = pr - next_item_size;
        let half = next_item_size / 2;
        if half > 0 && rem2 % half == 0 && rem2 / half <= 2 {
            score -= 9.0;
        }
        // reward residual that still holds a large fraction of capacity usable
        if (pr as f64) > cap * 0.5 && pr >= next_item_size * 2 {
            score -= 5.0;
        }
    }

    // NEW: sharper dead-space penalty scaled by fitting scarcity.
    // When few bins can host the next item, small unusable residuals hurt more.
    if next_item_size > pr && pr > 0 && fitting_bins_count <= 2 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
