            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 350.0;
    }

    // New-bin candidate handling: prefer new bin only when no good fit exists
    if bin_residual == bin_capacity {
        // base penalty so new bins are opened only when justified
        score += 90.0;
        // early in stream: opening bins is cheap (more bins amortized later)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 80.0 * (1.0 - progress);
        // if the item is large relative to capacity, new bin is attractive
        score -= (item_size as f64 / bin_capacity as f64) * 40.0;
        // many open bins with low mean residual: avoid opening another
        score += (open_bins_count as f64) * 6.0;
        if mean_residual > (item_size as f64) {
            score += 30.0;
        }
