        if next_item_size > 0 && bin_capacity == next_item_size {
            score -= 200.0;
        }
    } else {
        // Prefer tighter existing bins: tighter residual (bin_residual small) is better
        score += (bin_residual as f64) * 0.3;
    }

    // Late in the stream, consolidate into open bins rather than opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 50.0 * progress;
    }

    score
}

