    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for proliferation of open bins late in the stream
    score += 0.15 * open_bins_count as f64 * progress;

    // Smooth deviation from mean residual: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * cap * (0.3 + 0.7 * progress);

    // New-bin candidate: neutral-ish baseline, penalized when decent fits exist
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) + 2.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
