        // item sizes (10/20/25/50) are more reusable by future items.
        if pr % 10 == 0 {
            score -= 12.0;
        }
        if pr % 20 == 0 {
            score -= 6.0;
        }
        if pr % 25 == 0 {
            score -= 4.0;
        }
        if pr % 50 == 0 {
            score -= 4.0;
        }
        // Integer division thresholds: penalize large unusable chunks.
        let big_chunk = pr / 30; // 0,1,2,3
        score += big_chunk as f64 * 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (chain packing).
    if next_item_size > 0 && next_item_size <= pr {
        if next_item_size == pr {
            score -= 45.0;
        } else if pr - next_item_size <= 10 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > pr {
        // Next item cannot use this bin's leftover: penalize proportionally.
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Capacity fraction: prefer filling bins past 80% of capacity.
    let fill_frac = (bin_capacity - pr) as f64 / bin_capacity as f64;
    if fill_frac >= 0.8 {
        score -= 15.0 * fill_frac;
    } else {
        score += 10.0 * (0.8 - fill_frac);
    }

    // Stream progression: later in the stream, tighten up (avoid waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - (bin_residual as f64)) * 0.1;

    // New-bin candidate: make empty bin attractive only when no open bin
    // offers a tight fit (post_residual small or exact chain with lookahead).
    if bin_residual == bin_capacity {
        let tight_exists = pr <= 10 || (next_item_size > 0 && next_item_size <= pr && pr - next_item_size <= 10);
        if tight_exists {
            score += 100.0; // an open bin handles it well; keep new bin closed
        } else {
            score -= 5.0; // poor fits elsewhere: fresh bin is fine
        }
    }

    score
}

