        score += 0.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += pressure * (bin_residual as f64 - post_residual as f64) * 0.15;

    // Mean residual coupling: bins far from mean residual are either outliers;
    // prefer bins whose residual is close to (item_size + mean residual)/2 region.
    let target = mean_residual * 0.5 + item_size as f64 * 0.5;
    score += 0.2 * (bin_residual as f64 - target).abs();

    // Time horizon: early in stream, tolerate new bins (explore); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and as bins pile up.
        score += 35.0 * progress + 2.0 * open_bins_count as f64;
