    let r_norm = pr / cap;
    score += 14.0 * r_norm * (1.0 - r_norm) * (1.0 - progress);

    // Reward bins whose residual is consumed proportionally well by this item.
    let fill = it / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack_ok = if pr >= nxt { 1.0 } else { 0.0 };
        // smooth version
        let smooth = (pr / (pr + nxt)).min(1.0);
        score -= 8.0 * smooth * slack_ok.max(0.0);
        // penalize exact-consumption that strands next item
        if pr < nxt {
            score += 6.0 * (nxt - pr) / cap * 10.0;
        }
    }

    // Mild pressure to consolidate: prefer bins below mean residual early, above later.
    score += 0.05 * (pr - mean_residual) * (1.0 - 2.0 * progress);

    // Discard-new-bin pressure grows with open bins and progress.
    if bin_residual as f64 == cap {
        score += 12.0 + 8.0 * progress + 0.4 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Lookahead-driven gap shaping.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 52.0;
        } else if post_residual > next_item_size {
            let rem_after_next = post_residual - next_item_size;
            let tightness = 1.0 - (rem_after_next as f64) / 14.0;
            if tightness > 0.0 {
                score -= 34.0 * tightness;
            }
        } else {
            let dead_threshold = cap * 0.18;
            let dead = post_residual as f64;
            if dead < dead_threshold {
                score += 16.0 * (1.0 - dead / dead_threshold);
            }
        }
        // Two-item lookahead: reward residuals that fit both current and next item exactly.
        let sum2 = item_size as u32 + next_item_size;
        if sum2 > item_size && post_residual + item_size >= sum2 {
            let rem2 = post_residual - (next_item_size);
            if rem2 <= 3 {
                score -= 8.0;
            }
        }
    }

    // Exact / near-exact fit rewards.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 10.0;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Dead-space avoidance for small unusable gaps.
    let dead_max: u32 = 10;
    if post_residual > 0 && post_residual <= dead_max {
        score += (dead_max as f64 + 1.0 - post_residual as f64) * 12.0;
    }

    // Reward using the last fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean-residual pull: prefer bins whose leftover beats the average.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Mild open-bin pressure.
    score += open_bins_count as f64 * 1.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 60.0 - item_size as f64 * 0.45 + progress * 25.0;
        score += fitting_bins_count as f64 * 5.0;
        if post_residual >= 20 && post_residual <= 60 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual <= dead_max {
            score += (dead_max as f64 + 1.0 - post_residual as f64) * 12.0;
        }
        if progress > 0.7 {
            score += 15.0;
        }
    }

    // Slight preference for tighter bins among equally-good fits.
    score += (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual by its "usefulness class".
    let pr = post_residual;
    let frac = pr as f64 / cap;

    // Harmonic class penalty: residuals in (0,10] are near-dead space.
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if pr <= 10 {
        score += 45.0; // dead space penalty
    } else if pr <= 20 {
        score += 18.0;
    } else if pr <= 35 {
        score += 4.0;
    } else {
        // Larger residuals are more reusable; mild reward scaled by fraction
        score -= 6.0 * frac;
    }

    // Modulo-class logic: residuals that are multiples of common size
    // granularities (10, 20, 25) pair well with future items.
    let harmonic_bonus = if pr % 10 == 0 {
        8.0
    } else if pr % 5 == 0 {
        4.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead coupling: reward if next item fits exactly or well.
    if next_item_size > 0 && next_item_size <= pr {
        let next_gap = pr - next_item_size;
        if next_gap == 0 {
            score -= 55.0; // chains into a perfect fit
        } else if next_gap <= 10 {
            score -= 20.0;
        } else if next_gap <= 25 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // next item cannot use this residual: penalize proportionally
        score += 6.0 * (next_item_size as f64 - pr as f64) / cap;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // huge relative to capacity or many bins are already open with poor fits.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let base_new_bin_cost = 30.0;
        // Large items deserve fresh bins; small items should use leftovers.
        score += base_new_bin_cost - 40.0 * item_frac;
        // Early in the stream, building bins is fine; later, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If mean residual across open bins is large, prefer reusing them.
        score += (mean_residual / cap).min(1.0) * 12.0;
    }

    // Mild consolidation pressure: fewer open bins is better when fits exist.
    if bin_residual != bin_capacity {
        score -= 0.3 * open_bins_count as f64;
    }

    score
}

