    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here: small penalty for leaving a gap that blocks it
            score += 3.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize opening new bins / spreading out).
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it only
    // when the item is large and would leave a big awkward gap elsewhere, or when
    // mean residual across bins is small (existing bins are tight).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 10.0;
        // large items fit anywhere fresh; slight discount for big items
        score -= (item_size as f64 / cap) * 6.0;
        // if open bins are collectively tight, new bin is more attractive
        score -= (mean_residual / cap).max(0.0) * 12.0;
    } else {
        // placing into an existing bin is generally good: small standing discount
        score -= 4.0;
        // penalize leaving post_residual that is large but awkward (just above
        // typical item sizes -> likely wasted)
        let pr = post_residual as f64;
        if pr > 60.0 {
            score += 2.0;
        }
    }

    // Late in the stream, consolidation matters more: reward tight fits extra.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= fill_ratio * progress * 10.0;

    score
}

