            let gap = (post - nxt).abs();
            if post >= nxt {
                // next item fits after this one: reward closeness of match
                score -= (60.0 - gap.min(60.0)) * 2.0;
            } else {
                // next item would NOT fit in the leftover: penalize dead space
                score += gap * 1.5;
            }
            // penalize leaving a residual that is too small for the smallest
            // plausible item (dead space)
            if post < 10.0 && post > 0.0 {
                score += 150.0 * (1.0 - post / 10.0);
            }
        }
    }

    // Compare residual to mean: using a bin with below-average residual
    // (i.e., tighter bin) is good; leaving this item for a roomier bin is bad.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.25;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: opening a new bin is wasteful unless the item fits
    // nowhere else or the stream is early and bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = item_size as f64; // capacity lost by opening a fresh bin now
        let mut penalty = 300.0 + waste;
