    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space: post_residual that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size as f64 - post) / cap;
        score += 10.0 * waste * (1.0 + progress);
    } else if next_item_size > 0 {
        // Reward residual that exactly accommodates the lookahead item
        let gap = (post - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - gap).max(0.0) * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins early
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress) + 5.0;
    }

    // Mild penalty proportional to deviation from mean residual (prefer balanced fills)
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Prefer reusing bins over opening new ones as bins accumulate
    score += (open_bins_count as f64).ln() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of small sizes) are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // Usability of leftover: class by divisibility
        let class: f64 = if pr % 10 == 0 {
            -18.0 // clean class-10 leftover, easy to fill later
        } else if pr % 5 == 0 {
            -9.0
        } else if pr % 2 == 0 {
            -3.0
        } else {
            6.0 // odd leftover, awkward
        };
        score += class;

        // Integer-division dead-space threshold: leftover below 10 is nearly dead
        // (min item size historically 10, but be conservative for 1..100 range).
        if pr < 5 {
            score -= 25.0; // effectively full, great
        } else if pr < 10 {
            score += 15.0; // dead space penalty
        }

        // Harmonic fraction of capacity used
        let fill_frac = (bin_capacity - pr) as f64 / bin_capacity as f64;
        score -= fill_frac * 30.0;
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 20.0;
        } else if next_item_size > pr {
            score += 8.0; // next item can't use this bin's leftover anyway
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is penalized unless the
    // current item is large and would leave an awkward residual in any open bin.
    if bin_residual == bin_capacity {
        let awkward = pr > 0 && pr < 10;
        let big_item = item_size > bin_capacity / 2;
        let late = step_index as f64 / (total_items.max(1) as f64);
        let base = 70.0
            + if awkward { 40.0 } else { 0.0 }
            + if big_item { 10.0 } else { 0.0 }
            + late * 10.0
            - (open_bins_count as f64) * 2.0;
        score = score.max(base);
    }

    // Mild dispersion penalty: prefer bins below mean residual when residuals
    // are fragmented (keeps large holes concentrated in few bins).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Exact / near-exact fill
    if pr == 0 {
        score -= 50.0 * (0.6 + progress);
    } else if pr <= 2 {
        score -= 12.0;
    } else if pr <= 5 && next_item_size > 0 && next_item_size <= pr {
        score -= 7.0;
    } else if pr < 8 {
        score += 20.0 * (1.0 - pr as f64 / 8.0);
    }

    // Lookahead coupling with next item
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 52.0;
        } else if pr > next_item_size {
            let rem = pr - next_item_size;
            let tightness = 1.0 - rem as f64 / 14.0;
            if tightness > 0.0 {
                score -= 34.0 * tightness;
            } else {
                score -= 2.0;
            }
            if rem % 10 == 0 {
                score -= 6.0;
            }
            if rem == item_size {
                score -= 18.0;
            }
        } else {
            let dead_threshold = cap * 0.18;
            if pr < 10 {
                score += 20.0;
            } else if (pr as f64) < dead_threshold {
                score += 16.0 * (1.0 - pr as f64 / dead_threshold);
            }
        }
    }

    // Harmonic class reward
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Prefer bins tighter than the mean residual (bounded so it doesn't dominate)
    let mean_gap = (mean_residual - pr as f64).max(0.0);
    score -= 0.6 * mean_gap.min(30.0);

    // Small penalty for unusable small residuals
    if pr > 0 && (next_item_size == 0 || next_item_size > pr) && pr < 20 {
        score += (20 - pr) as f64 * 0.45;
    }

    // Two-item lookahead: chain-fill reward
    if next_item_size > 0 && pr > next_item_size {
        let rem2 = pr - next_item_size;
        if rem2 == item_size {
            score -= 20.0;
        }
        if rem2 > 0 && rem2 % next_item_size.max(1) == 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 0.8;
    }

    // New-bin candidate: baseline opening cost with adaptive discount
    if bin_residual == bin_capacity {
        score += 15.0;
        score -= (1.0 - progress) * 7.0 + open_bins_count as f64 * 0.4;
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        if item_size >= bin_capacity * 3 / 4 {
            score -= 7.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let poor = (open_bins_count - fitting_bins_count) as f64;
            if next_item_size > pr && poor / (open_bins_count.max(1) as f64) > 0.5 {
                score -= 6.0;
            }
        }
        // discourage opening fresh bins when a good fit exists (fit ratio high)
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if bin_residual == bin_capacity && fit_ratio < 0.25 && fitting_bins_count > 0 {
            score += 10.0;
        }
        score -= (pr as f64 / cap) * 6.0;
    }

    // Late-stream greediness
    if item_size == bin_residual {
        score -= 36.0 * (0.5 + progress);
    }

    // Dead-space ratio penalty
    if next_item_size > pr && pr > 0 {
        let waste_ratio = pr as f64 / cap;
        score += 14.0 * waste_ratio;
    }

    // Fractional-fit reward
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if item_size <= bin_residual && fill > 0.8 {
        score -= 10.0 * (fill - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to hold even the smallest plausible item.
    if post_residual > 0 {
        // Penalize small non-zero post residuals sharply (dead space).
        if post_residual < 12 {
            score += (12 - post_residual) as f64 * 6.0;
        }
        // Mild penalty for medium gaps that are unlikely to be filled well.
        else if post_residual < 25 {
            score += (25 - post_residual) as f64 * 1.5;
        }
        // Reward leaving a gap that can exactly fit a typical next item.
        else {
            score -= 4.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 8.0 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot fit in the residual, mild penalty proportional to closeness of miss.
    else if next_item_size > post_residual {
        let miss = (next_item_size - post_residual) as f64;
        if miss < 10.0 {
            score += miss * 0.8;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 2.0;
        // Extra penalty early in the stream when bins are cheap to reuse.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
    }

    // Coupling with mean residual: if this bin's residual is far above the mean,
    // it is a good candidate to absorb the item (it has extra room).
    let residual_diff = bin_residual as f64 - mean_residual;
    if residual_diff > 0.0 {
        score -= residual_diff * 0.3;
    } else {
        score += (-residual_diff) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
