    }

    // Mean-residual pull: prefer bins whose leftover beats the average.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // New-bin candidate handling (simplified, stronger to avoid premature opens).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 60.0 - item_size as f64 * 0.45 + progress * 25.0;
        score += fitting_bins_count as f64 * 5.0;
        if progress > 0.7 {
