    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize bins whose residual deviates far below the mean (hoarding space)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild pressure to prefer open bins over new bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;

    // Lookahead: reward bins that will be perfectly consumed by the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 56.0 ;
    } else if next_item_size > 0 && post_residual > next_item_size {
        let rem_after_next = post_residual - next_item_size ;
        let tightness = 1.0 - (rem_after_next as f64) / 13.0 ;
        if tightness > 0.0 {
