    if post_residual == 0 {
        score -= 26.0 ;
    } else if post_residual <= 2 {
        score -= 11.0 ;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 7.0 ;
    }

    // Spread bins: prefer bins below mean residual (keeps mid-size space alive)
    score -= 0.65 * (mean_residual - post_residual as f64) ;

    // New-bin candidate: only attractive when no open bin is tight-fitting
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 } ;
        let big_item = item_size as f64 / cap ;
        score += 6.0 + 20.0 * scarcity + 10.0 * big_item ;
    } else if fitting_bins_count <= 1 {
        // mildly prefer the unique fitting bin to avoid scattering
        score -= 3.0 ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

