    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild bonus scaled by how well it fills remainder
            let fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * fill;
        } else {
            // next item won't fit here: penalize leaving awkward gap
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            if gap < (item_size as f64) * 0.5 {
                score += 12.0;
            }
        }
    }

    // Prefer filling already-open bins when many bins are open (avoid bin proliferation).
    score += 0.6 * (open_bins_count as f64);

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 15.0 + 45.0 * progress;
        // But if mean residual is small and item is large, opening a bin is fine.
        if item_size as f64 > mean_residual * 0.8 {
