    } else {
        // Existing bin: reward more as stream progresses.
        score -= 15.0 * progress;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a laggard bin — prefer filling it.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.25 * dev;
    } else {
        score += 0.1 * (-dev);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
