pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;
    // Non-linear polynomial coupling of post residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * norm_item * (1.0 - progress);
    score += 40.0 * poly;
    // Reward tight fits (small post residual), stronger late in the stream
    let tight = 1.0 - norm_pr;
    score -= 30.0 * tight * tight * (0.5 + progress);
    // Penalize opening new bins early; encourage using them late
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) * (1.0 - progress) - 10.0 * progress;
    }
    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Dead space penalty: residuals too small for typical future items
    if pr > 0.0 && pr < next_item_size as f64 && next_item_size > 0 {
        score += 12.0 * (1.0 - pr / cap);
    }
    // Reward bins whose residual deviates favorably from mean residual
    score -= 0.2 * (mean_residual - pr);
    // Mild penalty for spreading across too many open bins
    score += 0.5 * (open_bins_count as f64).sqrt() * norm_pr;
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let res = post_residual as f64 ;

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 52.0 ;
    } else if next_item_size > 0 && post_residual > next_item_size {
        let rem_after_next = post_residual - next_item_size ;
        let tightness = 1.0 - (rem_after_next as f64) / 14.0 ;
        if tightness > 0.0 {
            score -= 34.0 * tightness ;
        }
        // mild lookahead: two-step chain fit
        if rem_after_next > 0 && rem_after_next <= 6 {
            score -= 8.0 * (1.0 - (rem_after_next as f64) / 6.0) ;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64 ;
        let dead_threshold = cap * 0.18 ;
        if dead < dead_threshold {
            score += 16.0 * (1.0 - dead / dead_threshold) ;
        }
        // penalize medium dead space that nothing upcoming can fill
        if dead >= dead_threshold && next_item_size > dead {
            score += 5.0 ;
        }
    }

    if post_residual == 0 {
        score -= 25.0 ;
    } else if post_residual <= 2 {
        score -= 10.0 ;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 ;
    }

    // new-bin candidate: discourage unless all open fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * (fitting_bins_count as f64) ;
    } else if fitting_bins_count <= 1 {
        score -= 4.0 ; // keep scarce fits attractive
    }

    // utilization-aware residual term
    let fill_ratio = 1.0 - res / cap ;
    score -= 0.6 * (mean_residual - res) ;
    score -= 4.0 * fill_ratio * (res / cap) ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // integer division thresholds (dead-space classes).
    let class = match post_residual {
        0 => 0u32,          // perfect fit
        1..=10 => 1,        // near-perfect
        11..=25 => 2,       // awkward small gap
        26..=50 => 3,       // medium gap
        _ => 4,             // large gap (wasteful placement)
    };
    score += match class {
        0 => -30.0,
        1 => -15.0,
        2 => 5.0,
        3 => 10.0,
        _ => 20.0,
    };

    // Modulo arithmetic: residual classes divisible by common item sizes
    // (10, 20, 25, 50) are more reusable.
    let reusable = post_residual % 10 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0;
    if reusable && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: reward bins whose post residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= (1.0 - gap as f64 / bin_capacity as f64) * 12.0;
        } else {
            // next item cannot follow here: penalize proportionally to leftover waste
            score += (post_residual as f64 / bin_capacity as f64) * 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 - 20.0 * progress + (open_bins_count as f64).sqrt() * 5.0;
        // new bin is acceptable if mean residual across open bins is tiny
        if mean_residual < item_size as f64 * 0.5 {
            score -= 55.0;
        }
    }

    // Tight-fit reward: prefer bins where the item fills a large fraction.
    score -= (item_size as f64 / bin_capacity as f64) * 6.0;

    // Small coupling: bins far below mean residual are "underused" -> slight penalty
    if bin_residual as f64 > mean_residual * 1.5 && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space
    // (smallest possible item is 1..100 here, but tiny gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strongly reward.
        score -= 100.0;
    }

    // Penalize moderate gaps that can only fit small future items less than
    // larger usable gaps: dead space scales quadratically near small residuals.
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 0.02 * (100.0 - pr) * (100.0 - pr) / 100.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading items; with few bins, tolerate spreading.
    let pressure = open_bins_count as f64;
    score += 0.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * pressure;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (chains two perfect fits).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // If next item would leave this bin with dead space regardless, mild penalty.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Early in the stream, be more willing to open bins (spread items);
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping looser bins available for larger items.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let cap = bin_capacity as f64 ;
    let res = bin_residual as f64 ;

    // Lookahead on next item fit
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 54.0 ;
    } else if next_item_size > 0 && post_residual > next_item_size {
        let rem_after_next = post_residual - next_item_size ;
        let tightness = 1.0 - (rem_after_next as f64) / 12.0 ;
        if tightness > 0.0 {
            score -= 36.0 * tightness ;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64 ;
        let dead_threshold = cap * 0.16 ;
        if dead < dead_threshold {
            score += 18.0 * (1.0 - dead / dead_threshold) ;
        }
    }

    // Near-perfect fills
    if post_residual == 0 {
        score -= 27.0 ;
    } else if post_residual <= 2 {
        score -= 11.0 ;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 7.0 ;
    }

    // Fragmentation pressure: bins with tiny residual relative to capacity are valuable to close out
    let frag = res / cap ;
    if frag > 0.0 && frag < 0.10 {
        score -= 9.0 * (1.0 - frag / 0.10) ;
    }

    // Scarcity of alternatives: when few bins can host this item, prefer them more strongly
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 5.0 ;
    }

    // New-bin candidate: discourage unless current bins are heavily loaded or item is large
    if bin_residual == bin_capacity {
        let load_ratio = 1.0 - (mean_residual / cap) ;
        let penalty = 20.0 + 14.0 * load_ratio ;
        if item_size >= (cap as u32 * 4 / 5) {
            score += penalty * 0.4 ;
        } else {
            score += penalty ;
        }
    }

    score -= 0.6 * (mean_residual - post_residual as f64) ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item -> strong reward
        if post_residual == next_item_size {
            score -= 40.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 10 {
            score -= 15.0 - diff;
        } else {
            score += diff * 0.5;
        }
        // Penalize leaving a residual that neither fits next item nor is useful
        if post_residual < next_item_size && post_residual > 0 {
            score += (post_residual as f64) * 0.3;
        }
    } else {
        // Last item: just prefer tightest fit
        score += 5.0;
    }

    // Compare post_residual relative to mean residual of open bins
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor,
    // but reward it late in the stream to avoid many half-empty bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    // Prefer filling nearly-full bins
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Mild penalty on too many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Dead-space avoidance: tiny residuals are hard to fill later.
    let dead_max: u32 = 14;
    if post_residual > 0 && post_residual <= dead_max {
        score += (dead_max as f64 + 1.0 - post_residual as f64) * 14.0;
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 2 {
        score -= 10.0;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Lookahead: reward leaving exactly the next item's size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 52.0;
        } else if post_residual > next_item_size {
            let rem_after_next = post_residual - next_item_size;
            let tightness = 1.0 - (rem_after_next as f64) / 14.0;
            if tightness > 0.0 {
                score -= 34.0 * tightness;
            }
        } else {
            let dead_threshold = cap * 0.18;
            if (post_residual as f64) < dead_threshold {
                score += 16.0 * (1.0 - post_residual as f64 / dead_threshold);
            }
        }
    }

    // Reward using the last fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild open-bin pressure.
    score += open_bins_count as f64 * 1.2;

    // Prefer bins tighter than the mean residual.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_score = 55.0 - item_size as f64 * 0.45;
        new_score += progress * 22.0;
        new_score += fitting_bins_count as f64 * 4.5;
        if post_residual >= 20 && post_residual <= 60 {
            new_score += 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 12 {
            new_score -= 18.0;
        }
        // Penalize opening a new bin when the item fits poorly nowhere but
        // an open bin would leave a large residual that matches the mean.
        if fitting_bins_count > 0 && post_residual > mean_residual + 25.0 {
            new_score += 8.0;
        }
        score = new_score;
    }

    // Slight preference for tighter bins.
    score += (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space (small but nonzero residuals that few items fit).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if the next item can fit into the post residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Extra reward for exact-ish chaining.
            let chain_waste = post_residual - next_item_size;
            score -= (10.0 - chain_waste.min(10) as f64).max(0.0);
        } else {
            // Penalize blocking the next item into this bin's leftover.
            score += 6.0;
        }
    }

    // Time horizon: early in the stream, be conservative about fragmenting bins;
    // later, exploit tight fits more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * fill_ratio;

    // Global state coupling: if mean residual across open bins is high,
    // prefer using existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
    }

    // New-bin candidate calibration: make an empty bin only attractive when
    // no good fit exists (its base score stays near capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
        if fitting_bins_count > 1 {
            score += 40.0;
        }
    }

    // Mild preference to fill bins with larger residuals when many bins are open.
    score += 0.02 * (open_bins_count as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress) * (1.0 - progress);

    let mut score = pr + 40.0 * poly;

    // Reward tight fits smoothly via cubic term on normalized post_residual.
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0 + 30.0 * progress;
    }

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 10.0 * (1.0 - (pr / (next_item_size.max(1) as f64)));
    }

    // Mild penalty when bin residual deviates from mean residual across open bins.
    score += 0.15 * (pr - mean_residual).abs();

    // Encourage consolidation when many bins are open.
    score += 2.0 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: penalize slightly so it is chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
