pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Moderate dead space: hard to fill later unless a small item arrives.
    if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead synergy: if the next item fits exactly into the post residual,
    // this placement chains nicely.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Bonus if it fills it completely.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual at all -> dead space likely.
        score += 6.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing ones rather than opening new bins.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += pressure + 20.0;
    } else {
        // Slight reward for using existing bins, scaled by pressure.
        score -= pressure * 0.2;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already tight; encourage filling tight bins.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    }

    // Progress: late in the stream, waste matters more (fewer chances to fix).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space avoidance: super-linear penalty for small unusable gaps.
    if pr > 0.0 {
        let dead_threshold = 10.0_f64;
        if pr < dead_threshold {
            score += (dead_threshold - pr) * (dead_threshold - pr) * 5.0;
        }
        score += pr * pr / cap * 0.5;
    } else {
        score -= 60.0;
    }

    // Reward tight fits relative to item size.
    if item_size > 0 && bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Open-bins pressure: encourage consolidation (mild, so tight fits still win).
    score += open_bins_count as f64 * 1.2;

    // Last-chance bonus: only fitting bin -> prefer it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening bins unless truly needed.
    if is_new_bin {
        score += 55.0 + open_bins_count as f64 * 2.0;
        if pr >= item_size as f64 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: exact-fit and tightness-aware.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 52.0;
        } else if post_residual > next_item_size {
            let rem_after_next = post_residual - next_item_size;
            let tightness = 1.0 - (rem_after_next as f64) / 14.0;
            if tightness > 0.0 {
                score -= 34.0 * tightness;
            }
        } else {
            let dead_threshold = cap * 0.18;
            if pr < dead_threshold {
                score += 16.0 * (1.0 - pr / dead_threshold);
            }
        }
    }

    // Mean-residual coupling: prefer bins whose post residual sits below the fleet mean.
    score -= 0.6 * (mean_residual - pr);
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.15;
    }

    // Stream progression: consolidate harder late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 {
        score += 8.0 * (1.0 - progress);
        if is_new_bin {
            score += 20.0 * progress;
        }
    }

    // Small residual bonuses.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 10.0;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Combined fine-grained fitting + lookahead: exact two-item chain bonus.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 18.0;
    }

    // New: mid-range dead-space shaping — penalize residuals that nothing
    // small could reuse, reward residuals near common small-item sizes.
    if !is_new_bin && pr > 5.0 && pr < 20.0 {
        score += 3.0;
        if next_item_size > 0 && next_item_size <= pr as u32 {
            score -= 4.0;
        }
    }

    // New: two-item lookahead gap check — avoid leaving a gap that fits
    // next item but leaves a tiny dead remainder afterward.
    if next_item_size > 0 && pr > next_item_size as f64 {
        let rem_after = pr - next_item_size as f64;
        if rem_after > 0.0 && rem_after < 3.0 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportional leftover after two placements
            let two_step_waste = post_residual - next_item_size;
            score -= 100.0 - two_step_waste as f64;
            if two_step_waste == 0 {
                score -= 400.0; // two-step perfect chain
            }
        } else {
            // next item cannot follow: penalize dead space creation
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Small residuals are hard to reuse; penalize small nonzero post_residual
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let base_penalty = 150.0;
        let large_item_discount = (item_size as f64 / bin_capacity as f64) * 120.0;
        score += base_penalty - large_item_discount;
    }

    // Slight preference for fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / bin_capacity as f64) * progress * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that no future item (min size 1..100) can use well,
    // but only when the gap is awkward (nonzero and small).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly or well into the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain_fit;
        } else {
            // Next item won't fit here; slight penalty for leaving a gap that traps us.
            score += 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize the brand-new-bin candidate so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening new bins is less costly (less time to waste space).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If the item is huge relative to capacity, a fresh bin is more attractive.
        score -= 0.2 * item_size as f64;
    }

    // Global state coupling: when mean residual across open bins is high, prefer bins
    // that reduce dispersion (i.e., bins with residual far below mean get a nudge).
    let dev = mean_residual - bin_residual as f64;
    score -= 0.08 * dev;

    // Mild time horizon: early in the stream, be more conservative with tight fits
    // (keep flexibility); later, commit to tight fits harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fill_ratio;

    // Slight penalty for spreading across too many open bins when many are already open.
    if bin_residual != bin_capacity {
        score += 0.15 * open_bins_count as f64 * (1.0 - fill_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Lookahead-driven gap shaping.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size {
            let rem_after_next = post_residual - next_item_size;
            let tightness = 1.0 - (rem_after_next as f64) / 12.0;
            if tightness > 0.0 {
                score -= 38.0 * tightness;
            }
        } else {
            let dead_threshold = cap * 0.15;
            if (post_residual as f64) < dead_threshold {
                score += 18.0 * (1.0 - post_residual as f64 / dead_threshold);
            }
        }
    }

    // Dead-space avoidance for small unusable gaps.
    let dead_max: u32 = 10;
    if post_residual > 0 && post_residual <= dead_max {
        score += (dead_max as f64 + 1.0 - post_residual as f64) * 14.0;
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 28.0;
    } else if post_residual <= 2 {
        score -= 12.0;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Reward using the last fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Mean-residual pull: prefer bins whose leftover beats the average.
    score -= 0.7 * (mean_residual - post_residual as f64);

    // Mild open-bin pressure.
    score += open_bins_count as f64 * 1.0;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of opening a new bin, discounted for large items.
        score = 65.0 - item_size as f64 * 0.5 + progress * 22.0;
        // Less justified when many open bins already fit the item.
        score += fitting_bins_count as f64 * 6.0;
        // Prefer open bins that leave a large usable residual.
        if post_residual >= 18 && post_residual <= 55 {
            score += 12.0;
        }
        // Dead-space penalty for the hypothetical new-bin placement.
        if post_residual > 0 && post_residual <= dead_max {
            score += (dead_max as f64 + 1.0 - post_residual as f64) * 14.0;
        }
        // Late in the stream, strongly consolidate.
        if progress > 0.7 {
            score += 18.0;
        }
        // Avoid opening a bin that cannot host the next item either.
        if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Slight preference for tighter bins among equally-good fits.
    score += (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr * (1.0 + 0.35 * progress * pr / cap + 0.15 * (1.0 - progress) * (pr / cap).powi(2));

    // Reward tight fits (small post_residual), scaled by progress
    let tightness = -(cap - pr) * (0.4 + 0.6 * progress);

    // Penalize dead space that next item cannot use
    let mut score = poly + tightness;
    if next_item_size > 0 && (pr as u32) < next_item_size {
        score += 8.0 * (1.0 - progress) + 4.0;
    }
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 3.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: mildly penalize early, allow late when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * progress + 0.05 * mean_residual * (open_bins_count as f64).sqrt();
    }

    // Small penalty for opening many bins relative to mean residual spread
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "wasteful" the leftover is
    // relative to capacity fractions (1/4, 1/3, 1/2).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else {
        // Dead-space classification via integer-division thresholds
        if post_residual <= bin_capacity / 4 {
            score -= 60.0; // small leftover likely reusable
        } else if post_residual <= bin_capacity / 3 {
            score -= 20.0;
        } else if post_residual <= bin_capacity / 2 {
            score += 15.0;
        } else {
            score += 40.0; // huge leftover: bin was nearly empty
        }

        // Modulo harmonic classes: residuals that are multiples of common
        // item-size classes (10s) are more likely to be filled later.
        if post_residual % 10 == 0 {
            score -= 12.0;
        }
        if post_residual % 5 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward; if it cannot ever fit, penalize dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: prefer reusing an existing bin unless it
    // is nearly empty and the item is small.
    if bin_residual == bin_capacity {
        // brand-new bin: neutral-ish baseline; penalize slightly so existing
        // bins with decent fits win, but keep it competitive when fits are bad.
        score += 25.0 + mean_residual * 0.1;
    } else {
        // Tightness reward: the smaller the wasted fraction, the better.
        let tightness = 1.0 - (post_residual as f64) / cap;
        score -= tightness * 30.0;
    }

    // Late in the stream, consolidation matters more: favor bins below mean
    // residual (more filled) to close them out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post - mean_residual) * (0.2 + 0.4 * progress);

    // Mild preference for filling bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space avoidance: super-linear penalty for small unusable gaps.
    if pr > 0.0 {
        let dead_threshold = 10.0_f64;
        if pr < dead_threshold {
            score += (dead_threshold - pr) * (dead_threshold - pr) * 4.5;
        }
        score += pr * pr / cap * 0.45;
    } else {
        score -= 65.0;
    }

    // Reward tight fits relative to item size.
    if item_size > 0 && bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 28.0;
    }

    // Open-bins pressure: encourage consolidation.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: only fitting bin -> prefer it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 34.0;
    }

    // New-bin candidate handling: penalize opening new bins more strongly,
    // unless the new bin would swallow a large item that open bins can't host.
    if is_new_bin {
        score += 52.0 + open_bins_count as f64 * 1.8;
        if pr >= item_size as f64 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: exact-fit and tightness-aware (core of the best heuristic).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size {
            let rem_after_next = post_residual - next_item_size;
            let tightness = 1.0 - (rem_after_next as f64) / 14.0;
            if tightness > 0.0 {
                score -= 36.0 * tightness;
            }
            // Two-item chain: item + next exactly fills residual.
            if item_size as u64 + next_item_size as u64 == bin_residual as u64 {
                score -= 20.0;
            }
        } else {
            let dead_threshold = cap * 0.16;
            if pr < dead_threshold {
                score += 18.0 * (1.0 - pr / dead_threshold);
            }
        }
    }

    // Mean-residual coupling: prefer bins whose post residual sits below the
    // fleet mean residual, rewarding aggressive fill.
    score -= 0.65 * (mean_residual - pr);
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.18;
    }

    // Stream progression: consolidate harder late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 {
        score += 9.0 * (1.0 - progress);
        if is_new_bin {
            score += 24.0 * progress;
        }
    }

    // Small residual bonuses.
    if post_residual == 0 {
        score -= 28.0;
    } else if post_residual <= 2 {
        score -= 12.0;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10 band)
    // are pure waste; penalize proportionally to how close we are to a "dead" gap.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Non-linear penalty for medium-small gaps that most items cannot use.
    if post_residual > 0 && post_residual <= 30 {
        score += (30.0 - post_residual as f64).powf(1.4) * 0.6;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 25.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading; penalize candidates that leave large residuals when
    // bin count is high.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial reward proportional to how well next item uses the leftover.
        score -= (next_item_size as f64 / post_residual.max(1) as f64) * 10.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual. Make it
    // attractive only when existing bins would create bad fits (large post_residual
    // or dead space), otherwise keep it slightly worse than a decent fit.
    if bin_residual == bin_capacity {
        let good_fit_available = mean_residual > item_size as f64 * 1.5 && post_residual >= 0;
        if good_fit_available && open_bins_count > 0 {
            score += 30.0 + pressure * 5.0;
        } else {
            // Fresh bin gives full flexibility; mildly reward when nothing fits well.
            score -= 15.0;
        }
    }

    // Mild stream-progression coupling: late in the stream, waste matters more
    // since fewer items remain to fill gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64 / bin_capacity as f64) * progress * 15.0;

    // Mean-residual coupling: if this bin's residual is far below the mean, it is
    // a laggard bin; using it evens out residuals (desirable).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Dead-space avoidance: tiny residuals are hard to fill later.
    let dead_max: u32 = 14;
    if post_residual > 0 && post_residual <= dead_max {
        score += (dead_max as f64 + 1.0 - post_residual as f64) * 14.0;
