    // Exact fit is gold.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 2 {
        score -= 10.0;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Lookahead: reward leaving exactly the next item's size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 52.0;
        } else if post_residual > next_item_size {
            let rem_after_next = post_residual - next_item_size;
            let tightness = 1.0 - (rem_after_next as f64) / 14.0;
            if tightness > 0.0 {
                score -= 34.0 * tightness;
            }
        } else {
            let dead_threshold = cap * 0.18;
            if (post_residual as f64) < dead_threshold {
                score += 16.0 * (1.0 - post_residual as f64 / dead_threshold);
            }
        }
    }

    // Reward using the last fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild open-bin pressure.
    score += open_bins_count as f64 * 1.2;

    // Prefer bins tighter than the mean residual.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_score = 58.0 - item_size as f64 * 0.45;
        new_score += progress * 22.0;
        new_score += fitting_bins_count as f64 * 4.5;
        // Large items justify a fresh bin more readily.
        if item_size >= 60 {
            new_score -= 8.0;
        }
        // If an open bin would leave a large usable residual, prefer it.
        if post_residual >= 20 && post_residual <= 60 {
            new_score += 10.0;
        }
        // Lookahead: opening a fresh bin is fine if next item can pair with it.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 12 {
            new_score -= 18.0;
        }
        // Penalize opening a new bin when a tight fit exists among open bins.
        if fitting_bins_count > 0 && post_residual <= 4 {
            new_score += 12.0;
        }
        score = new_score;
    }

    // Slight preference for tighter bins.
    score += (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match lookahead: post_residual can host next item with small waste
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space: post_residual too small to fit next item (unusable gap)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 20.0;
    }

