        if progress > 0.65 {
            score += 20.0;
        }
        // Avoid opening a bin that cannot host the next item either.
        if next_item_size > post_residual {
            score += 9.0;
        }
        // Big items justify fresh bins more strongly.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Slight preference for tighter bins among equally-good fits.
    score += (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
