        if pr < nx {
            score += 20.0 * (nx - pr) / cap * (1.0 + t);
        } else {
            // reward residuals that leave room for the next item
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bonus: only fitting bin => strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - t);
    }

    // Mild penalty when this bin's residual deviates from mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Discard penalty for near-perfect fill later in stream
    score -= 15.0 * (1.0 - pr_norm) * pr_norm * (1.0 + 2.0 * t);

    score
}

