pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // integer-division bands relative to capacity fractions.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap_f; // 0.0 .. 1.0

    // Harmonic band index: 0 => near-perfect fit, higher => more wasted space
    let band = (post_residual * 4) / bin_capacity; // integer division: 0..=3
    let band_penalty = match band {
        0 => -18.0, // residual < C/4 : excellent packing
        1 => -6.0,  // residual < C/2 : decent
        2 => 4.0,   // residual < 3C/4 : mediocre
        _ => 10.0,  // large dead space
    };
    score += band_penalty;

    // Modulo-arithmetic "compatibility": does next_item_size divide into
    // post_residual cleanly? If next item fits exactly (post_residual %
    // next == 0 and next > 0), strongly reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            if post_residual % next_item_size == 0 {
                score -= 14.0;
            } else {
                // partial harmonic alignment: how close is next to post
                let gap = (post_residual - next_item_size) as f64;
                score -= 8.0 * (1.0 - gap / cap_f).max(0.0);
            }
        } else {
            // next item cannot use this residual at all: penalize wasted
            // potential proportionally to how big the leftover is
            score += 5.0 * frac;
        }
    }

    // Last-chance bin: only one bin can fit this item; avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current fit is poor or many bins are open with
    // large mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let poor_fit = frac > 0.5; // this call is the empty bin => frac == 1
        let _ = poor_fit;
        let fragmentation = if open_bins_count > 0 { mean_residual / cap_f } else { 0.0 };
        // prefer new bin when existing bins are fragmented or this item
        // would leave big dead space elsewhere
        let item_class = (item_size * 4) / bin_capacity;
        let bonus = if item_class >= 2 { 20.0 } else { 6.0 };
        score = 30.0 + bonus - 25.0 * fragmentation;
        // late in the stream, consolidating is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Mild global regularization: tighter bins preferred as stream grows
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * frac * progress;

    // Penalize residuals that fall into awkward harmonic classes relative
    // to typical item sizes (multiples of 10 assumed common)
    let mod10 = post_residual % 10;
    if mod10 != 0 && post_residual < item_size.max(next_item_size) {
        score += 2.0; // awkward sliver no common item can use
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: penalize post_residual, with extra weight for small unusable gaps.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 200.0;
    } else if post_residual < 10 {
        // Dead space: gap too small for any item.
        score += 150.0 + pr;
    } else {
        score += pr;
        // Extra penalty if gap can't fit the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0;
        }
    }

    // Reward using tight bins (small residual before placement).
    score += bin_residual as f64 * 0.3;

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 60.0 + 8.0 * open_bins_count as f64;
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it.
        score -= 120.0;
    }

    // Slight preference toward bins with below-average residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual as f64 ;
    let it = item_size as f64 ;
    let nxt = next_item_size as f64 ;
    let cap = bin_capacity as f64 ;
    let progress = step_index as f64 / (total_items as f64 + 1.0) ;
    // dead space created by this placement
    let dead_threshold = if pr < it { pr } else { 0.0 } ;
    score += 2.8 * dead_threshold ;
    // lookahead: penalty when residual after placement cannot host next item
    if nxt > 0.0 && pr > 0.0 && pr < nxt {
        let gap = nxt - pr ;
        let tightness = 1.0 - (pr / (nxt + 1.0)) ;
        let weight = 0.55 + 0.95 * tightness - 0.25 * progress ;
        score += weight * gap ;
        if fitting_bins_count <= 1 && bin_residual != bin_capacity {
            score += 0.8 * gap ;
        }
    }
    // exact/near-exact match of post residual with next item: strong reward
    if pr > 0.0 && nxt > 0.0 && (pr - nxt).abs() < 1.0 && bin_residual != bin_capacity {
        score -= 60.0 ;
    }
    // sole fitting bin: strong preference to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0 ;
    }
    // tight-fit bonus scaled by item size
    let tightness = 1.0 - pr / cap ;
    score -= 0.35 * it * tightness ;
    // deviation from mean residual
    let dev = mean_residual - bin_residual as f64 ;
    let dev_w = if fitting_bins_count > 1 { 0.75 } else { 0.45 } ;
    score += dev_w * dev ;
    // penalize bins left with large slack fraction (avoid scattered leftovers)
    let frac = bin_residual as f64 / cap ;
    if frac > 0.45 && bin_residual != bin_capacity {
        score += 9.0 * (frac - 0.45) ;
    }
    // new-bin candidate handling
    if bin_residual == bin_capacity {
        if pr <= 2.0 && nxt > 0.9 * cap {
            score -= 20.0 ;
        } else {
            let pressure = (nxt / cap).min(1.0) ;
            score += 6.0 + 0.05 * open_bins_count as f64 + 30.0 * (1.0 - pressure) ;
            if fitting_bins_count > 2 {
                score += 25.0 ;
            }
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space avoidance: super-linear penalty for small unusable gaps,
    // scaled by the item so small items tolerate small gaps.
    if pr > 0.0 {
        let dead_threshold = (12.0_f64).min(it * 0.5);
        if pr < dead_threshold {
            let d = dead_threshold - pr;
            score += d * d * 4.0;
        }
        score += pr * pr / cap * 0.5;
    } else {
        score -= 60.0;
    }

    // Reward tight fits relative to item size.
    if item_size > 0 && bin_residual > 0 {
        let fill_ratio = it / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Open-bins pressure: encourage consolidation.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: only fitting bin -> prefer it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the
    // leftover would be nearly full-capacity-blocking; otherwise charge a
    // moderate cost that grows with consolidation pressure late in stream.
    if is_new_bin {
        if pr <= 2.0 && next_item_size as f64 > 0.9 * cap {
            score -= 20.0;
        } else {
            let late_gate = 40.0 + open_bins_count as f64 * 1.2 + 14.0 * progress;
            score += late_gate;
        }
    }

    // Lookahead coupling: exact-fit and tightness-aware.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 52.0;
        } else if post_residual > next_item_size {
            let rem_after_next = post_residual - next_item_size;
            let tightness = 1.0 - (rem_after_next as f64) / 14.0;
            if tightness > 0.0 {
                score -= 34.0 * tightness;
            }
        } else {
            // Can't fit next item: penalize gaps just below next item size,
            // weighted by tightness (borrowed from best heuristic).
            let gap = next_item_size as f64 - pr;
            let tightness = 1.0 - pr / (next_item_size as f64 + 1.0);
            let weight = 0.55 + 0.95 * tightness - 0.25 * progress;
            score += weight * gap;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below fleet mean.
    let dev = mean_residual - bin_residual as f64;
    if fitting_bins_count > 1 {
        score += 0.75 * dev;
    } else {
        score += 0.45 * dev;
    }
    score -= 0.6 * (mean_residual - pr);

    // Stream progression: consolidate harder late in the stream.
    if progress > 0.7 {
        score += 8.0 * (1.0 - progress);
        if is_new_bin {
            score += 20.0 * progress;
        }
    }

    // Small residual bonuses.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 10.0;
    } else if post_residual <= 5 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Combined fine-grained fitting + lookahead: exact two-item chain bonus.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 18.0;
    }

    // Penalize large mostly-empty bins (waste guard, borrowed from best),
    // with a late-stream escalation to squeeze residual space.
    let frac = bin_residual as f64 / cap;
    if frac > 0.45 && !is_new_bin {
        score += 9.0 * (frac - 0.45) * (1.0 + 0.8 * progress);
    }

    // Anti-dead-space guard: residual slightly below a typical small item
    // is worse than residual near zero; nudge selection toward emptier bins.
    if !is_new_bin && pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 * 0.35 {
        score += 2.0 * (next_item_size as f64 * 0.35 - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    score -= (item_size as f64) * 0.5;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
            // Exact chain fit: post_residual equals next item perfectly.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Penalize dead space that cannot serve the next item,
            // scaled by how much space is wasted.
            let dead = (post_residual as f64) - (next_item_size as f64).min(post_residual as f64);
            score += dead * 0.3;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins exist and the fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0;
        // But allow new bin if post_residual is huge (item tiny) and next item
        // would leave current bin useless anyway.
        if next_item_size > 0 && post_residual > 60 {
            score -= 10.0;
        }
    }

    // Late-stream bias: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
