    // dead-space penalty: waste created now, slightly stronger for large items
    let dead_threshold = if pr < it { pr } else { 0.0 } ;
    score += (2.8 + 0.6 * (it / cap)) * dead_threshold ;
    // lookahead: penalize residual too small for next item, weighted by tightness
    if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
