    let dev = mean_residual - br ;
    let dev_w = if fitting_bins_count > 1 { 0.75 } else { 0.45 } ;
    score += dev_w * dev ;
    // discourage leaving large-but-not-full residuals open
    let frac = br / cap ;
    if frac > 0.45 && bin_residual != bin_capacity {
        score += 9.0 * (frac - 0.45) ;
    }
    // new-bin candidate logic
    if bin_residual == bin_capacity {
        if pr <= 2.0 && next_item_size as f64 > 0.9 * cap {
            score -= 20.0 ;
        } else {
            // opening a new bin is more acceptable when few bins fit the item
            let relief = if fitting_bins_count <= 1 { 3.0 } else { 0.0 } ;
            score += 6.0 + 0.05 * open_bins_count as f64 - relief ;
        }
    } else if fitting_bins_count == 1 {
        // sole fitting bin: mild reward to keep chains alive
        score -= 0.35 * (1.0 - frac) ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

