    // so use a soft threshold around 15% of capacity).
    let dead_threshold = 0.15 * bin_capacity as f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * tightness;
    }

    // New-bin candidate handling: empty bin should only win when the fit in open bins is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases late in the stream when future
        // demand is uncertain but also when many bins are open (consolidation).
        score += 35.0 - 10.0 * progress;
        // If the next item is large and would fit alongside nothing, opening fresh is fine.
        if next_item_size > 0 && (next_item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 8.0;
        }
        // Many open bins with high mean residual: prefer existing bins (avoid fragmentation).
        score += (open_bins_count as f64).sqrt() * 2.0;
        score += (mean_residual / bin_capacity as f64).max(0.0) * 15.0;
    } else {
        // Prefer bins whose residual is close to mean (balanced packing) mildly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Lookahead: if next item fits exactly in the post-residual, reward this placement.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Next item won't fit here anyway; slight penalty if post residual becomes tiny.
            score += 3.0;
        }
    }

    // Mild global pressure: when many bins are open, discourage opening new ones
    // (handled above) and encourage tight fills.
    score -= (open_bins_count as f64).ln().max(0.0) * tightness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
