    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot follow in this bin; mild penalty scaled by overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.15;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Global state: when many bins are open with slack, discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins exist and mean residual is large.
        score += open_bins_count as f64 * 6.0 + mean_residual * 0.5;
        // Early in the stream, new bins are cheaper; late, prefer consolidation.
        score += (1.0 - progress) * 20.0;
