    // Time horizon coupling: as stream progresses, weight tightness more.
    score -= tightness * progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = pr_norm * (1.0 + 1.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post residual with stream progress:
    // early on, tolerate loose fits; later, penalize wasted space quadratically
    let coupling = pr_norm * (1.0 - progress) - pr_norm * pr_norm * progress;
    score += 2.0 * coupling * coupling;

    // Dead-space penalty: post residual too small for typical future items
    if pr < 10.0 {
        score += (10.0 - pr) * 0.5;
    }

    // Last-chance bonus: only fitting bin — strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    } else {
        // mild penalty when many alternatives exist to keep tight bins for later
        score += (fitting_bins_count as f64).ln() * 0.3 * progress;
    }

    // Lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 3.0 * fit_quality * fit_quality * (0.5 + 0.5 * progress);
        } else {
            score += 1.0;
        }
    }

    // Open-bin pressure: many open bins -> discourage fragmenting, favor filling
    let bin_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 1.5 * bin_pressure * pr_norm * (1.0 + progress);

    // Mean residual alignment: prefer bins whose residual is below mean (tighter)
    let mr = mean_residual / cap;
    score += (pr_norm - mr).abs() * 0.8;

    // New-bin candidate: empty bin gets a moderate default cost; opened only
    // when all open bins score worse
    if bin_residual == bin_capacity {
        score = 6.0 + 4.0 * progress - (fitting_bins_count as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

