    // Modulo-class coupling: residuals near multiples of common item sizes
    // (e.g. 25, 50, 75) are more reusable; reward them.
    let m25 = (post_residual % 25) as f64;
    score -= 6.0 * (1.0 - (m25 / 12.5 - 1.0).abs());

