        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 + 10.0 * (1.0 - gap / cap);
        if gap == 0.0 {
            score -= 20.0; // perfect chain fit
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how close
        // we came (wasted potential).
        let miss = (next_item_size - post_residual) as f64;
        if miss < 20.0 {
            score += 8.0 * (1.0 - miss / 20.0);
        }
    }

    // --- Last-chance bin: strongly prefer using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only good when current bins are quite full
        // (low mean residual) or the item is large and fits poorly elsewhere.
        let mean_r = mean_residual.max(0.0);
        score += 25.0 - 20.0 * (mean_r / cap);
        if item_size >= 50 && post_residual < 50 {
            score -= 5.0; // large item into fresh bin keeps flexibility
