    // --- Tightness reward: closer fit (small post_residual) is better ---
    score -= 10.0 * (1.0 - frac);

    // --- Stream progression: as stream ends, prefer closing bins tightly ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * frac;

    // Slight preference to keep number of open bins moderate.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * frac;

    score
}

