        if fitting_bins_count <= 1 && bin_residual != bin_capacity {
            score += 0.8 * gap ;
        }
    }
    // reward slack that can still host next item, scaled by how snugly it fits
    if nxt > 0.0 && pr >= nxt {
        let slack = pr - nxt ;
        if slack < 0.35 * cap {
            score += 0.9 * slack * (1.0 - slack / cap) ;
        }
    }
    // near-exact fit reward: residual exactly matches next item
    if pr > 0.0 && nxt > 0.0 && (pr - nxt).abs() < 1.0 && bin_residual != bin_capacity {
        score -= 60.0 ;
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0 ;
    }
    // tight-fit bonus scaled by item size
    let tightness = 1.0 - pr / cap ;
    score -= 0.35 * it * tightness ;
    let dev = mean_residual - bin_residual as f64 ;
    let dev_w = if fitting_bins_count > 1 { 0.75 } else { 0.45 } ;
    score += dev_w * dev ;
    // tiny-waste penalty: small dead fraction is valuable, don't squander it
    if pr > 0.0 && pr < it {
        let waste_frac = pr / cap ;
        score += 4.0 * waste_frac * (1.0 + 0.5 * (pr / it)) ;
    }
    // near-full bonus
    if pr > 0.0 && pr <= 4.0 && bin_residual != bin_capacity {
        score -= 1.5 ;
    }
    // penalize bins left with large slack fraction (avoid scattered leftovers)
    let frac = bin_residual as f64 / cap ;
    if frac > 0.45 && bin_residual != bin_capacity {
        score += 9.0 * (frac - 0.45) ;
    }
    // new-bin candidate handling
    if bin_residual == bin_capacity {
        let big_next = nxt > 0.9 * cap ;
        if pr <= 2.0 && big_next {
            score -= 20.0 ;
        } else if nxt > 0.0 && nxt <= it && fitting_bins_count <= 1 {
            // next item fits in this fresh bin alongside current: mild reward
            score -= 6.0 ;
        } else if nxt > 0.0 && nxt > pr && pr >= it && nxt <= 0.5 * cap && fitting_bins_count <= 2 {
            score -= 2.5 ;
        } else {
            let pressure = (nxt / cap).min(1.0) ;
            score += 6.0 + 0.05 * open_bins_count as f64 + 30.0 * (1.0 - pressure) ;
            if fitting_bins_count > 2 {
                score += 25.0 ;
            }
        }
    } else {
        if pr == 0.0 {
            score -= 0.8 ;
        }
        let dead_frac = if it > 0.0 { (bin_residual as f64 - it) / cap } else { 0.0 } ;
        if dead_frac > 0.0 && dead_frac < 0.08 {
            score += 1.2 * (1.0 - dead_frac / 0.08) ;
        }
        if nxt > 0.0 && pr > 0.0 && pr >= nxt && pr - nxt < 2.0 {
            score -= 1.0 ;
        }
    }
    score
}

